actions.script:
if (System.getProperty('tax.qa.disposable') != 'true' || !ec.user.isInGroup('ADMIN') ||
    ec.entity.find('mantle.party.Party').condition('partyId','TAX_QA_A').disableAuthz().count()) {
 ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
ec.entity.makeDataLoader().location('component://zenith-erp-tax/TaxQaFixture.xml').load()
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
['TAX_QA_USER','TAX_QA_VIEW'].each { id ->
 def qa=ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
 ['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each { qa.set(it,demo.get(it)) }
 qa.disabled='N';qa.update()
}
ec.web.sendJsonResponse([initialized:true])

if (System.getProperty('tax.qa.disposable') != 'true' || !(ec.user.username in ['tax.qa','tax.viewer','john.doe'])) {
 ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def calls=[
 autoTcs:'zenith.erp.india.TdsServices.checkAndApply#TcsOnSales',sales:'zenith.sales.SalesInvoiceServices.create#SalesInvoice',purchase:'zenith.purchase.PurchaseServices.create#PurchaseInvoice',purchaseItem:'zenith.purchase.PurchaseServices.add#PurchaseInvoiceItem',tax:'zenith.tax.TaxServices.calculate#Tax',gst:'zenith.india.GstServices.calculate#Gst',
 gstin:'zenith.india.GstServices.validate#Gstin',registration:'zenith.tax.TaxServices.create#TaxRegistration',
 updateRegistration:'zenith.tax.TaxServices.store#TaxRegistration',deleteRegistration:'zenith.tax.TaxServices.delete#TaxRegistration',
 exemption:'zenith.tax.TaxServices.store#TaxExemption',deleteExemption:'zenith.tax.TaxServices.delete#TaxExemption',
 checkExemption:'zenith.tax.TaxServices.check#TaxExemption',getRegistration:'zenith.tax.TaxServices.get#PartyTaxRegistration',
 rate:'zenith.tax.TaxServices.store#TaxRate',authority:'zenith.tax.TaxServices.store#TaxAuthority',
 engine:'zenith.tax.TaxServices.save#TaxEngineConfig',globalTax:'zenith.tax.TaxServices.calculate#GlobalTax',
 gstr1:'zenith.india.Gstr1Services.generate#Gstr1Data',exportGstr1:'zenith.india.Gstr1Services.export#Gstr1Json',
 gstr2:'zenith.india.Gstr2Services.generate#Gstr2Data',gstr3b:'zenith.india.Gstr2Services.generate#Gstr3bData',
 charged:'zenith.india.GstServices.get#ChargedInvoiceTax',lines:'zenith.tax.TaxServices.get#DashboardTaxLines',scope:'zenith.tax.TaxAccessServices.get#AuthorizedActiveOrganization',words:'zenith.india.GstServices.convert#AmountToIndianWords',tcs:'zenith.india.GstServices.calculate#TcsOnSales',
 einvoice:'zenith.india.EinvoiceServices.generate#Einvoice',eway:'zenith.india.EwayBillServices.generate#EwayBill',distance:'zenith.india.EwayBillServices.calculate#EwayBillDistance',qr:'zenith.india.EinvoiceServices.generate#DynamicUpiQr',ewayRequired:'zenith.india.EwayBillServices.check#EwayBillRequired',taxSummary:'zenith.tax.TaxServices.get#TaxSummary',taxLines:'zenith.tax.TaxServices.get#TaxLineDetails',tracker:'zenith.india.GstServices.update#TcsCumulativeTracker'
]
if(ec.web.parameters.op=='resetScope') {ec.user.setPreference('ACTIVE_ORGANIZATION','TAX_QA_A');ec.web.sendJsonResponse([reset:true]);return}
if(ec.web.parameters.op=='forgeScope') {
 ec.user.setPreference('ACTIVE_ORGANIZATION','TAX_QA_B');ec.web.sendJsonResponse([forged:true]);return
}
def service=calls[ec.web.parameters.op]
if (!service) {ec.web.response.setStatus(400);ec.web.sendJsonResponse([denied:true]);return}
def params=new groovy.json.JsonSlurper().parseText(ec.web.parameters.input ?: '{}')
// Every record selector and org is synthetic. No arbitrary service or entity invocation.
['organizationPartyId','tenantId','partyId','customerPartyId','productId','invoiceId','registrationId','exemptionId'].each { key ->
 if(key=='invoiceId' && params[key] && !params[key].toString().startsWith('TAX_QA_')) {def inv=ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId',params[key]).one();if(inv?.fromPartyId?.startsWith('TAX_QA_') && inv?.toPartyId?.startsWith('TAX_QA_'))return}
 if(params[key] && !params[key].toString().startsWith('TAX_QA_')) throw new IllegalArgumentException('Synthetic identifiers required')
}
def result=ec.service.sync().name(service).parameters(params).call()
def errors=new ArrayList(ec.message.errors);ec.message.clearErrors()
ec.web.sendJsonResponse([result:result,errors:errors])
